from math import comb
class Solution:
    def getProbability(self, balls):
        k = len(balls)
        n = sum(balls) // 2
        total = comb(sum(balls), n)
        self.ans = 0
        def dfs(i, left, d1, d2, w):
            if i == k:
                if left == 0 and d1 == d2:
                    self.ans += w
                return
            rem = sum(balls[i+1:])
            for x in range(max(0, left - rem), min(balls[i], left) + 1):
                dfs(i + 1, left - x, d1 + (x > 0), d2 + (x < balls[i]),
                    w * comb(balls[i], x))
        dfs(0, n, 0, 0, 1)
        return self.ans / total

