class Solution {
public:
    double ans = 0;
    long long C(int a, int b) {
        long long r = 1;
        for (int i = 0; i < b; i++) r = r * (a - i) / (i + 1);
        return r;
    }
    void dfs(vector<int>& b, int i, int left, int d1, int d2, long long w) {
        if (i == (int)b.size()) {
            if (left == 0 && d1 == d2) ans += w;
            return;
        }
        int rem = 0;
        for (int j = i + 1; j < (int)b.size(); j++) rem += b[j];
        for (int x = max(0, left - rem); x <= min(b[i], left); x++)
            dfs(b, i + 1, left - x, d1 + (x > 0), d2 + (x < b[i]),
                w * C(b[i], x));
    }
    double getProbability(vector<int>& balls) {
        int s = accumulate(balls.begin(), balls.end(), 0);
        dfs(balls, 0, s / 2, 0, 0, 1);
        return ans / C(s, s / 2);
    }
};

