from math import comb
from functools import lru_cache
class Solution:
    def getProbability(self, balls):
        k = len(balls)
        n = sum(balls) // 2
        @lru_cache(maxsize=None)
        def dp(i, left, d1, d2):
            if i == k:
                return float(left == 0 and d1 == d2)
            res = 0.0
            lo = max(0, left - sum(balls[i+1:]))
            for x in range(lo, min(balls[i], left) + 1):
                res += comb(balls[i], x) * dp(i + 1, left - x,
                        d1 + (x > 0), d2 + (x < balls[i]))
            return res
        return dp(0, n, 0, 0) / comb(2 * n, n)

