    map<array<int,4>, double> memo;
    vector<int> b;
    long long C(int a, int c) {
        long long r = 1;
        for (int i = 0; i < c; i++) r = r * (a - i) / (i + 1);
        return r;
    }
    double dp(int i, int left, int d1, int d2) {
        if (i == (int)b.size()) return (left == 0 && d1 == d2) ? 1.0 : 0.0;
        array<int,4> key = {i, left, d1, d2};
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        double res = 0;
        int rem = 0;
        for (int j = i + 1; j < (int)b.size(); j++) rem += b[j];
        for (int x = max(0, left - rem); x <= min(b[i], left); x++)
            res += C(b[i], x) * dp(i + 1, left - x, d1 + (x > 0), d2 + (x < b[i]));
        return memo[key] = res;
    }
    double getProbability(vector<int>& balls) {
        b = balls;
        int s = accumulate(balls.begin(), balls.end(), 0);
        return dp(0, s / 2, 0, 0) / C(s, s / 2);
    }
};

