var getProbability = function(balls) {
    const C = (a, b) => { let r = 1; for (let i = 0; i < b; i++) r = r * (a - i) / (i + 1); return r; };
    const memo = new Map();
    const suffix = balls.map((_, i) => balls.slice(i + 1).reduce((a, b) => a + b, 0));
    const dp = (i, left, d1, d2) => {
        if (i === balls.length) return (left === 0 && d1 === d2) ? 1 : 0;
        const key = i + ',' + left + ',' + d1 + ',' + d2;
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        for (let x = Math.max(0, left - suffix[i]); x <= Math.min(balls[i], left); x++)
            res += C(balls[i], x) * dp(i + 1, left - x,
                d1 + (x > 0 ? 1 : 0), d2 + (x < balls[i] ? 1 : 0));
        memo.set(key, res);
        return res;
    };
    const s = balls.reduce((a, b) => a + b, 0);
    return dp(0, s / 2, 0, 0) / C(s, s / 2);
};
